theorem Tengoku.ObserverEquivarianceLean.PreservesCleavage.map_chi (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) {s t : S} (u : s ⟶ t) (y : O) (hy : p.obj y = t)
    {hy' : p.obj (F.obj y) = A.obj t}
    (hsrc : F.obj (d.reind u y hy) = d.reind (A.map u) (F.obj y) hy') :
    F.map (d.chi u y hy) = eqToHom hsrc ≫ d.chi (A.map u) (F.obj y) hy'

theorem Tengoku.ObserverEquivarianceLean.isTwistedEquivariant_comp {F F' : O ⥤ O} {θ θ' : MulAut G}
    (h : IsTwistedEquivariant d θ F) (h' : IsTwistedEquivariant d θ' F') :
    IsTwistedEquivariant d (θ' * θ) (F ⋙ F')

theorem Tengoku.ObserverEquivarianceLean.isTwistedEquivariant_inv {F Finv : O ⥤ O} {θ : MulAut G}
    (hi : F ⋙ Finv = 𝟭 O) (ih : Finv ⋙ F = 𝟭 O) (h : IsTwistedEquivariant d θ F) :
    IsTwistedEquivariant d θ⁻¹ Finv

theorem Tengoku.ObserverEquivarianceLean.preservesCleavage_comp {F F' : O ⥤ O} {A A' : S ⥤ S}
    (pc : PreservesCleavage d F A) (pc' : PreservesCleavage d F' A') :
    PreservesCleavage d (F ⋙ F') (A ⋙ A')

theorem Tengoku.ObserverEquivarianceLean.preservesCleavage_inv {F Finv : O ⥤ O} {B : StrictAut S}
    (hi : F ⋙ Finv = 𝟭 O) (ih : Finv ⋙ F = 𝟭 O)
    (pc : PreservesCleavage d F B.hom) : PreservesCleavage d Finv B.inv

theorem eq_liftOver {s t : S} {u : s ⟶ t} {x y : O} {hx : p.obj x = s} {hy : p.obj y = t}
    (f : x ⟶ y) (hf : p.map f = eqToHom hx ≫ u ≫ eqToHom hy.symm) :
    f = m.liftOver u hx hy

theorem Tengoku.ObserverEquivarianceLean.parallel_basepoints_const_unique [Nonempty S] (d d' : OEData G p) {c c' : G}
    (hc : ∀ s, d'.base s = d.act (d.base s) c) (hc' : ∀ s, d'.base s = d.act (d.base s) c') :
    c = c'

theorem Tengoku.ObserverEquivarianceLean.eq_liftByMultiplierθ (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    (hF : IsTwistedEquivariant d θ F) (hc : F ⋙ p = p ⋙ A) :
    F = liftByMultiplierθ d A θ (liftMultiplier d F)

theorem Tengoku.ObserverEquivarianceLean.exists_unique_eq_liftFunctor_comp_Λ (d : OEData G p) [IsConnected S] {F : O ⥤ O}
    {A : S ⥤ S} (hF : IsGEquivariant d F) (pc : PreservesCleavage d F A) :
    ∃! a : G, F = liftFunctor d A ⋙ Λ d a

theorem Tengoku.ObserverEquivarianceLean.exists_unique_eq_liftFunctorθ_comp_Λ (d : OEData G p) [IsConnected S] {θ : MulAut G}
    {F : O ⥤ O} {A : S ⥤ S} (hF : IsTwistedEquivariant d θ F) (pc : PreservesCleavage d F A) :
    ∃! a : G, F = liftFunctorθ d A θ ⋙ Λ d a

theorem Tengoku.ObserverEquivarianceLean.liftMultiplier_const (d : OEData G p) [IsConnected S] {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) (s t : S) :
    liftMultiplier d F s = liftMultiplier d F t

theorem Tengoku.ObserverEquivarianceLean.liftMultiplier_eq_of_hom (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) {s t : S} (u : s ⟶ t) :
    liftMultiplier d F s = liftMultiplier d F t

theorem Tengoku.ObserverEquivarianceLean.lift_obj_act_base_twisted (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    (hF : IsTwistedEquivariant d θ F) (hc : F ⋙ p = p ⋙ A) (s : S) (g : G) :
    F.obj (d.act (d.base s) g) = d.act (d.base (A.obj s)) (liftMultiplier d F s * θ g)

theorem Tengoku.ObserverEquivarianceLean.multiplier_unique (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S} {k : S → G}
    (hk : ∀ x, F.obj x = d.act (d.base (A.obj (p.obj x))) (k (p.obj x) * d.coord x)) :
    k = liftMultiplier d F

theorem Tengoku.ObserverEquivarianceLean.multiplier_unique_twisted (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    {k : S → G}
    (hk : ∀ x, F.obj x = d.act (d.base (A.obj (p.obj x))) (k (p.obj x) * θ (d.coord x))) :
    k = liftMultiplier d F

theorem Tengoku.ObserverEquivarianceLean.preservesCleavage_iff_exists_base_obj (d : OEData G p) [IsConnected S] {F : O ⥤ O}
    {A : S ⥤ S} (hF : IsGEquivariant d F) (hc : F ⋙ p = p ⋙ A) :
    PreservesCleavage d F A ↔ ∃ c : G, ∀ s, F.obj (d.base s) = d.act (d.base (A.obj s)) c

theorem Tengoku.ObserverEquivarianceLean.sectionFunctor_comp_eq_of_obj (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (hc : F ⋙ p = p ⋙ A) (c : G) (h : ∀ s, F.obj (d.base s) = d.act (d.base (A.obj s)) c) :
    d.sectionFunctor ⋙ F = A ⋙ d.sectionFunctor ⋙ d.actFunctor c

@[simp] theorem componentMultiplier_mk (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) (s : S) :
    componentMultiplier d pc (compMk s) = liftMultiplier d F s

theorem liftMultiplier_factors_through_components (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) :
    ∃! κ : CategoryTheory.ConnectedComponents S → G, ∀ s, liftMultiplier d F s = κ (compMk s)

theorem Tengoku.ObserverEquivarianceLean.natTrans_descent_of_eq (m : MinSpec G p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem Tengoku.ObserverEquivarianceLean.natTrans_descent_of_eq (d : OEData G p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem Tengoku.ObserverEquivarianceLean.natTrans_descent_of_eq (σ : StrictSection p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem Tengoku.ObserverEquivarianceLean.IsHolLift.obj_pt {ρ : Γ →* G} {F : HolTotal Γ G ⥤ HolTotal Γ G}
    {A : SingleObj Γ ⥤ SingleObj Γ} (hF : IsHolLift ρ F A) (x : HolTotal Γ G) :
    (F.obj x).2.pt = (F.obj (holBase (SingleObj.star Γ))).2.pt * x.2.pt

theorem Tengoku.ObserverEquivarianceLean.holFunctor_ext {C : Type*} [Category C] {F F' : C ⥤ HolTotal Γ G}
    (hobj : ∀ x, F.obj x = F'.obj x)
    (hmap : ∀ {x y : C} (f : x ⟶ y), ((F.map f).1 : Γ) = (F'.map f).1) : F = F'

theorem Tengoku.ObserverEquivarianceLean.recordSpace_val_congr {τ : ℝ} {I : RecDom} (x : recordSpace τ I) {j k : Fin 3}
    (hj : j ∈ I.dom) (hk : k ∈ I.dom) (h : j = k) :
    (x : ↥I.dom → ℝ) ⟨j, hj⟩ = (x : ↥I.dom → ℝ) ⟨k, hk⟩

theorem Tengoku.ObserverEquivarianceLean.OEData.IsInvariant.verticallyTrivial_iff_residualAction_trivial {d : OEData G p}
    {F : O ⥤ C} (hF : d.IsInvariant F) :
    VerticallyTrivial p F ↔ ∀ s, residualAction d F hF s = 1

theorem Tengoku.ObserverEquivarianceLean.isInvariantNatTrans_comp (d : OEData G p) {F F' F'' : O ⥤ C} {hF : OEData.IsInvariant d F}
    {hF' : OEData.IsInvariant d F'} {hF'' : OEData.IsInvariant d F''} {α : F ⟶ F'} {β : F' ⟶ F''}
    (hα : IsInvariantNatTrans d hF hF' α) (hβ : IsInvariantNatTrans d hF' hF'' β) :
    IsInvariantNatTrans d hF hF'' (α ≫ β)
